constexpr int CONCURRENT_LIMIT = 5;

// Initialize semaphore with capacity 5
// (Initial counter value is CONCURRENT_LIMIT)
std::counting_semaphore<CONCURRENT_LIMIT> resource_pool(CONCURRENT_LIMIT);

void access_resource() {
    // Acquire/Wait (P operation):
    // Decrements counter. Blocks if counter is zero.
    resource_pool.acquire();

    // --- Critical Section ---
    // (Only 5 threads allowed here concurrently)

    // Release/Signal (V operation):
    // Increments counter. May unblock a waiting thread.
    resource_pool.release();
}

// Check counter state without blocking:
bool available = resource_pool.try_acquire();
